<script setup>import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Icon from '@/Components/UI/Icon.vue';import HrNav from '../Partials/HrNav.vue';import HrPageHeader from '../Partials/HrPageHeader.vue';import PlanningForm from './PlanningForm.vue';defineOptions({layout:AppLayout});const props=defineProps({employees:[Array,Object],departments:[Array,Object],selectedEmployeeUuid:String});const form=useForm({employee_uuid:props.selectedEmployeeUuid??'',department_uuid:'',title:'',starts_at:'',ends_at:'',observation:''});const submit=()=>form.post('/administration/planning');</script><template><Head title="Nouveau créneau"/><div class="space-y-5"><HrNav/><HrPageHeader eyebrow="Planning · Affectation guidée" title="Ajouter un créneau" description="Sélectionnez un employé et une période. Son département est repris automatiquement sauf si vous indiquez une affectation différente." icon="calender-date" tone="sky"><template #actions><Link href="/administration/planning" class="inline-flex h-10 items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 text-sm font-bold text-slate-600 hover:border-cyan-300 hover:text-cyan-600 dark:border-gray-800 dark:bg-gray-950 dark:text-slate-200"><Icon name="arrow-left"/> Retour au planning</Link></template></HrPageHeader><PlanningForm :form="form" :employees="employees" :departments="departments" cancel-href="/administration/planning" submit-label="Ajouter au planning" @submit="submit"/></div></template>
